-- =====================================================================
-- Migration 4: question bank seed (60 original questions, 4 rounds x 15)
-- Stable identifiers live in `slug`. Edit, add or deactivate questions with
-- a new migration (or the SQL editor + a recorded migration) - no frontend
-- changes needed. Re-running is safe: existing slugs are updated in place.
-- =====================================================================

on conflict (slug) do update
  set category          = excluded.category,
      question_text     = excluded.question_text,
      discussion_prompt = excluded.discussion_prompt,
      display_order     = excluded.display_order;
